const body = $json.body || $json;

return [{
  json: {
    authorized: body.apiKey === 'travelmind_secure_001',
    destination: body.destination || 'your destination',
    days: Number(body.days || 3),
    budgetAmount: Number(body.budget || 50000),
    travelers: Number(body.travelers || 1),
    interests: body.interests || 'general sightseeing',
    preferences: body.preferences || 'balanced pace',
    startDate: body.startDate || '',
    endDate: body.endDate || '',
    travelStyles: body.travelStyles || []
  }
}];

const data = $json;

data.itinerary = Array.from({ length: data.days }, (_, i) => ({
  day: i + 1,
  morning: `Explore a signature area of ${data.destination} with a focus on ${data.interests}.`,
  afternoon: `Visit a popular attraction, market, or cultural stop in ${data.destination}.`,
  evening: `Enjoy dinner and a relaxed evening matched to: ${data.preferences}.`
}));

return [{ json: data }];

const data = $json;
const budget = data.budgetAmount;

data.totalBudget = budget;
data.budget = {
  stays: Math.round(budget * 0.35),
  food: Math.round(budget * 0.2),
  transport: Math.round(budget * 0.2),
  activities: Math.round(budget * 0.2),
  buffer: Math.round(budget * 0.05)
};

return [{ json: data }];

